bash -lc "applypatch << 'PATCH'
*** Begin Patch
*** Update File: src/libxml2/xinclude.c
@@
-    cur = ctxt->incTab[nr]->ref;
-    if ((cur == NULL) || (cur->type == XML_NAMESPACE_DECL))
-        return(-1);
+    cur = ctxt->incTab[nr]->ref;
+    /*
+     * Be defensive: cur may have already been freed by the time this
+     * function is invoked (e.g. during heap-use-after-free scenarios
+     * reported by ASAN). Do not dereference a possibly freed node.
+     */
+    if (cur == NULL)
+        return(-1);
+    if (cur->type == XML_NAMESPACE_DECL) {
+        /* Mark the referenced node as non-persistent for this inc slot */
+        ctxt->incTab[nr]->ref = NULL;
+        return(-1);
+    }
*** End Patch
PATCH" }

bash -lc "perl -0777 -pe 's/cur = ctxt->incTab\[nr\]\->ref;
\s*if \(\(cur == NULL\) \|\| \(cur->type == XML_NAMESPACE_DECL\)\)
\s*return\(-1\);/cur = ctxt->incTab[nr]->ref;
    /* defensive: cur may be freed; avoid dereferencing a freed node */
    if (cur == NULL) {
        return(-1);
    }
    if (cur->type == XML_NAMESPACE_DECL) {
        ctxt->incTab[nr]->ref = NULL;
        return(-1);
    }/s' -i /src/libxml2/xinclude.c && echo DONE && nl -ba /src/libxml2/xinclude.c | sed -n '2188,2225p'"

bash -lc "ed -s /src/libxml2/xinclude.c <<'ED'
2194,2196c
    cur = ctxt->incTab[nr]->ref;
    if (cur == NULL)
        return(-1);
    if (cur->type == XML_NAMESPACE_DECL) {
        ctxt->incTab[nr]->ref = NULL;
        return(-1);
    }
.
wq
ED" && echo PATCH_XINCLUDE_DONE"

